/// The entity type's health and category; `None` for a non-living type.
pub fn mob(entity: EntityKind) -> Option<&'static Mob> {
    MOBS.binary_search_by_key(&entity.id(), |m| m.entity.id())
        .ok()
        .and_then(|i| MOBS.get(i))
}
